-- SELECT only. Run after apply. 예/아니오 항목은 모두 예, 그 밖의 값은 precheck의 같은 이름 항목과 같은 값이어야 한다.
select 'history row present' as item,case when (select count(*) from supabase_migrations.schema_migrations where version='20261029120000' and name='todo_candidates_telegram')=1 then '예' else '아니오' end as value
union all select 'source kind check has seven kinds and is validated',case when (select count(*) from pg_constraint where conrelid=to_regclass('public.app_todo_candidates') and conname='app_todo_candidates_source_kind_check' and convalidated and pg_get_constraintdef(oid) like '%project_update%' and pg_get_constraintdef(oid) like '%telegram%')=1 then '예' else '아니오' end
union all select 'telegram function: definer, empty search_path, no anon or PUBLIC execute',case when exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.app_todo_candidate_from_telegram(uuid,uuid,text,text,date)') and p.prosecdef and p.proconfig=array['search_path=""'] and not has_function_privilege('anon',p.oid,'execute') and coalesce(p.proacl::text,'')!~'(^|[{,])=') then '예' else '아니오' end
union all select 'telegram function: service_role only',case when has_function_privilege('service_role','public.app_todo_candidate_from_telegram(uuid,uuid,text,text,date)','execute') and not has_function_privilege('authenticated','public.app_todo_candidate_from_telegram(uuid,uuid,text,text,date)','execute') then '예' else '아니오' end
union all select 'candidates: service_role and anon still have no table privilege',case when not has_any_column_privilege('service_role','public.app_todo_candidates','select,insert,update,references') and not has_any_column_privilege('anon','public.app_todo_candidates','select,insert,update,references') then '예' else '아니오' end
union all select 'candidates rows',(select count(*)::text from public.app_todo_candidates)
union all select 'candidates grants policies hash',md5(coalesce((select string_agg(c.relname||':'||c.relrowsecurity::text||':'||coalesce(c.relacl::text,''),',' order by c.relname) from pg_class c where c.oid=to_regclass('public.app_todo_candidates')),'')
  ||coalesce((select string_agg(a.attname||':'||coalesce(a.attacl::text,''),',' order by a.attname) from pg_attribute a where a.attrelid=to_regclass('public.app_todo_candidates') and a.attnum>0 and not a.attisdropped),'')
  ||coalesce((select string_agg(p.polname::text||p.polcmd::text||p.polroles::text||coalesce(pg_get_expr(p.polqual,p.polrelid),'')||coalesce(pg_get_expr(p.polwithcheck,p.polrelid),''),',' order by p.polname) from pg_policy p where p.polrelid=to_regclass('public.app_todo_candidates')),''));
